// Build Apify input for harvestapi/linkedin-profile-posts.
// Reads watchlist rows from previous node, produces a single input object.
const MAX_POSTS_PER_RUN = parseInt($env.APIFY_MAX_POSTS_PER_RUN || '500', 10);
const profiles = $input.all().map((i) => i.json);
const targetUrls = profiles
  .filter((p) => p.profile_id)
  .map((p) =>
    p.profile_id.startsWith('http')
      ? p.profile_id
      : `https://www.linkedin.com/in/${p.profile_id}/`,
  );
const maxPostsPerProfile = Math.max(1, Math.floor(MAX_POSTS_PER_RUN / Math.max(targetUrls.length, 1)));
return [{
  json: {
    actorPrimary: 'harvestapi~linkedin-profile-posts',
    actorFallback1: 'harvestapi~linkedin-post-search',
    actorFallback2: 'apimaestro~linkedin-posts-search-scraper-no-cookies',
    activeProfileIds: profiles.map((p) => p.profile_id),
    apifyInput: {
      targetUrls,
      maxPosts: maxPostsPerProfile,
      scrapeReactions: false,
      scrapeComments: true,
      maxComments: 10,
      postedLimitDate: new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString(),
      includeQuotePosts: false,
      includeReposts: false,
    },
  },
}];

