// validate_and_route — Zod minimal schema gate.
// Output 1 (main[0]): valid posts paired with their actor id.
// Output 2 (main[1]): DLQ entries.
const actorId = $('Code: build_apify_input').first().json.actorPrimary; // overwritten per branch below if fallback
const rawPosts = $input.all().map((i) => i.json);

// Minimal schema check inline (mirrors apifyPostMinimalSchema).
function extractMinimal(p) {
  // HarvestAPI shape
  const post_id = p.id || p.urn || p.postId || '';
  const author = p.author || {};
  const author_id = author.publicIdentifier || author.urn || author.profileId || p.authorUrn || '';
  const postedAt = p.postedAt || p.publishedAt || p.posted_at || p.time;
  let published_at = '';
  if (typeof postedAt === 'string') published_at = postedAt;
  else if (postedAt && typeof postedAt === 'object') published_at = postedAt.date || postedAt.iso || '';
  else if (typeof postedAt === 'number') published_at = new Date(postedAt < 1e12 ? postedAt*1000 : postedAt).toISOString();
  const text = (p.content || p.text || '').toString().replace(/\s+/g, ' ').trim();
  return { post_id, author_id, published_at, text };
}

const valid = [], dlq = [];
for (const raw of rawPosts) {
  const m = extractMinimal(raw);
  const missing = ['post_id','author_id','published_at','text'].filter((k) => !m[k]);
  if (missing.length > 0) {
    dlq.push({ raw_payload: raw, source_actor: actorId, error_reason: `minimal_schema_failed:missing:${missing.join(',')}` });
  } else {
    valid.push({ raw, minimal: m, source_actor: actorId });
  }
}
return [
  valid.map((v) => ({ json: v })),
  dlq.map((d) => ({ json: d })),
];

// map_to_raw_posts — produces rows ready for raw_posts UPSERT.
// Delegates to the appropriate field mapping based on source_actor.
const DAY_MAP = { Mon:'Lun', Tue:'Mar', Wed:'Mer', Thu:'Jeu', Fri:'Ven', Sat:'Sam', Sun:'Dim' };
function parisParts(date) {
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone:'Europe/Paris', weekday:'short', hour:'2-digit', hour12:false });
  const p = fmt.formatToParts(date);
  const get = (t) => p.find((x) => x.type === t)?.value || '';
  const hr = parseInt(get('hour'), 10);
  return { weekday: DAY_MAP[get('weekday')] || 'Lun', hour: hr === 24 ? 0 : hr };
}
function safeInt(v, d=0) { const n = typeof v === 'number' ? v : parseInt(String(v ?? ''), 10); return Number.isFinite(n) ? Math.max(0, n) : d; }
function detectMedia(raw) {
  if (raw.document || raw.documentUrl || raw.document_url) return 'document';
  if (raw.video || raw.videoUrl || raw.video_url) return 'video';
  const imgs = raw.postImages || raw.images || raw.media;
  if (Array.isArray(imgs)) {
    if (imgs.length > 1) return 'carrousel';
    if (imgs.length === 1) return 'image';
  }
  return 'texte';
}
function topComments(raw) {
  const arr = raw.comments;
  if (!Array.isArray(arr) || arr.length === 0) return null;
  return arr.map((c) => ({
    author: (c.author && c.author.name) || c.authorName || 'unknown',
    text: (c.commentary || c.text || c.content || '').toString(),
    likes: safeInt(c.likes ?? c.reactions ?? c.likesCount),
  })).filter((c) => c.text).sort((a,b) => b.likes - a.likes).slice(0, 5);
}

const rows = $input.all().map((i) => {
  const { raw, minimal, source_actor } = i.json;
  const d = new Date(minimal.published_at);
  const p = parisParts(d);
  const eng = raw.engagement || {};
  const reactions = raw.reactions || {};
  return {
    json: {
      post_id: minimal.post_id,
      profile_id: minimal.author_id,
      published_at: d.toISOString(),
      day_of_week: p.weekday,
      hour_of_day: p.hour,
      text: minimal.text,
      media_type: detectMedia(raw),
      likes: safeInt(eng.likes ?? reactions.LIKE ?? raw.likes ?? raw.like_count),
      comments: safeInt(eng.comments ?? raw.comments_count ?? raw.commentsCount),
      reposts: safeInt(eng.shares ?? raw.share_count ?? raw.reposts ?? raw.shares),
      views_estimees: raw.views != null ? safeInt(raw.views) : (raw.view_count != null ? safeInt(raw.view_count) : null),
      url: raw.linkedinUrl || raw.url || raw.post_url || null,
      comment_sample: topComments(raw),
      source_actor,
    },
  };
});
return rows;

// normalizer (inline port of packages/n8n-nodes/src/normalizer.ts).
// Source of truth: TypeScript module, tested in __tests__/normalizer.test.ts.
// This inline JS uses a French stopword HEURISTIC instead of franc-min because
// n8n cloud Code Nodes don't load arbitrary npm modules. Accuracy gap acceptable
// for the FR/non-FR cut after the > 200 char prefilter.
//
// Inputs:  raw_posts rows from previous node.
// Outputs: three items — { type:'clean_posts', items }, { type:'temporal_rows', items }, { type:'stats', ... }.
// Author baselines & followers expected via $vars (workflow variables); fall back to empty maps.

const FR_STOPWORDS = new Set(['le','la','les','de','des','du','un','une','et','à','au','aux','pour','que','qui','dans','sur','avec','par','ne','pas','est','sont','cette','ces','mais','ou','donc','son','sa','ses','nos','votre','vos','leur','leurs','comme','plus','tout','tous','dont','où','être','avoir','fait','faire','peut','très','aussi','encore','même','déjà']);
function isFrench(text) {
  if (!text || text.length < 50) return false;
  const words = text.toLowerCase().split(/[\s,.!?;:'"()\[\]…—\-]+/).filter((w) => w.length > 0);
  if (words.length < 20) return false;
  let n = 0;
  for (const w of words) if (FR_STOPWORDS.has(w)) n += 1;
  return n / words.length >= 0.06;
}
const SELF_PROMO = [/réservez\s+(votre|une)\s+démo/i,/lien\s+(en|dans)\s+bio/i,/cliquez\s+ici\s+pour/i,/n[''']hésitez\s+pas\s+à\s+me\s+contacter/i,/\bdm\s+moi\b/i,/inscrivez-vous\s+(à|au)\s+(notre|mon)/i,/profitez\s+de\s+[0-9]+\s*%/i,/offre\s+(spéciale|limitée)/i];
function isSelfPromo(t) { return SELF_PROMO.some((re) => re.test(t)); }
const TOPIC_RULES = [['pilotage',/\b(s\/p|loss\s*ratio|ratio\s*combiné|ibnr|prime\s+d[''']équilibre|dérive)\b/i],['commercial',/\b(bordereau|commission|rétrocession|rétention|apporteur|churn)\b/i],['reglementaire',/\b(acpr|rgpd|audit\s+trail|conformité|défendabilité)\b/i],['operationnel',/\b(sinistre|indemnisation|\bij\b|fraude|\bmrp\b|\brc\s*pro\b)\b/i],['tech_ia',/\b(agent\s+ia|llm|claude|gpt|automation|n8n)\b/i],['marche_assurance',/\b(mga|mutuelle|courtage|insurtech|réassureur|embedded)\b/i]];
function detectCluster(t) { for (const [c, re] of TOPIC_RULES) if (re.test(t)) return c; return 'autre'; }
const DAY_MAP = { Mon:'Lun', Tue:'Mar', Wed:'Mer', Thu:'Jeu', Fri:'Ven', Sat:'Sam', Sun:'Dim' };
function parisParts(date) {
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone:'Europe/Paris', year:'numeric', month:'2-digit', day:'2-digit', weekday:'short', hour:'2-digit', hour12:false });
  const p = fmt.formatToParts(date);
  const g = (t) => p.find((x) => x.type === t)?.value || '';
  const hr = parseInt(g('hour'), 10);
  return { year:+g('year'), month:+g('month'), day:+g('day'), weekday: DAY_MAP[g('weekday')] || 'Lun', hour: hr === 24 ? 0 : hr };
}
function isoWeek(p) {
  const u = new Date(Date.UTC(p.year, p.month-1, p.day));
  const dn = u.getUTCDay() || 7;
  u.setUTCDate(u.getUTCDate() + 4 - dn);
  const ys = new Date(Date.UTC(u.getUTCFullYear(), 0, 1));
  const w = Math.ceil(((u.getTime() - ys.getTime())/86400000 + 1)/7);
  return u.getUTCFullYear() + '-W' + String(w).padStart(2,'0');
}
function hourBucket(h) {
  if (h>=6 && h<8) return '06h-08h';
  if (h>=8 && h<10) return '08h-10h';
  if (h>=10 && h<12) return '10h-12h';
  if (h>=12 && h<14) return '12h-14h';
  if (h>=14 && h<17) return '14h-17h';
  if (h>=17 && h<19) return '17h-19h';
  if (h>=19 && h<21) return '19h-21h';
  return 'autre';
}

const baselines = $vars && $vars.authorBaselines ? new Map(Object.entries($vars.authorBaselines)) : new Map();
const followers = $vars && $vars.followersByAuthor ? new Map(Object.entries($vars.followersByAuthor)) : new Map();
const activeIds = $vars && $vars.activeProfileIds ? new Set($vars.activeProfileIds) : null;
const rawPosts = $input.all().map((i) => i.json);
const seen = new Set(), clean = [], rejected = [], temporal = new Map();

for (const p of rawPosts) {
  if (seen.has(p.post_id)) continue;
  seen.add(p.post_id);
  if (activeIds && (!p.profile_id || !activeIds.has(p.profile_id))) { rejected.push({ post_id: p.post_id, reason: 'off_watchlist' }); continue; }
  const text = p.text || '';
  if (text.length < 200) { rejected.push({ post_id: p.post_id, reason: 'too_short' }); continue; }
  if (!isFrench(text)) { rejected.push({ post_id: p.post_id, reason: 'non_fr' }); continue; }
  if (isSelfPromo(text)) { rejected.push({ post_id: p.post_id, reason: 'self_promo' }); continue; }
  const eRaw = (p.likes || 0) + (p.comments || 0) * 3 + (p.reposts || 0) * 5;
  const knownB = baselines.get(p.profile_id);
  const baseline = knownB !== undefined ? Number(knownB) : (eRaw > 0 ? eRaw : 1);
  const ratio = eRaw / Math.max(baseline, 1);
  if (ratio < 0.8) { rejected.push({ post_id: p.post_id, reason: 'below_author_baseline' }); continue; }
  const flw = Number(followers.get(p.profile_id) || 1000);
  const ff = Math.log10(flw + 1) / Math.log10(100000);
  const score = ratio * (1 + 0.3 * (1 / Math.max(ff, 0.01)));
  const cluster = detectCluster(text);
  clean.push({ post_id: p.post_id, engagement_score_normalized: score, is_relevant: true, topic_cluster_pre: cluster, filter_reason: null, processed_at: new Date().toISOString() });
  const parts = parisParts(new Date(p.published_at));
  const wk = isoWeek(parts), hb = hourBucket(parts.hour);
  const key = wk + '|' + parts.weekday + '|' + hb;
  let b = temporal.get(key);
  if (!b) { b = { week_id: wk, day_of_week: parts.weekday, hour_bucket: hb, count: 0, sum: 0, formats: {} }; temporal.set(key, b); }
  b.count += 1; b.sum += score;
  const mt = p.media_type || 'texte';
  b.formats[mt] = (b.formats[mt] || 0) + 1;
}

const temporalRows = [...temporal.values()].map((b) => {
  const dist = {};
  let topFmt = 'texte', topCnt = -1;
  for (const [k, v] of Object.entries(b.formats)) {
    dist[k] = v / b.count;
    if (v > topCnt) { topCnt = v; topFmt = k; }
  }
  return { week_id: b.week_id, day_of_week: b.day_of_week, hour_bucket: b.hour_bucket, posts_count: b.count, avg_engagement_norm: b.sum / b.count, top_format: topFmt, format_distribution: dist };
});

const breakdown = rejected.reduce((acc, r) => { acc[r.reason] = (acc[r.reason] || 0) + 1; return acc; }, { off_watchlist: 0, too_short: 0, non_fr: 0, self_promo: 0, below_author_baseline: 0 });

return [
  { json: { type: 'clean_posts', items: clean } },
  { json: { type: 'temporal_rows', items: temporalRows } },
  { json: { type: 'stats', total_in: rawPosts.length, kept: clean.length, rejected: rejected.length, rejected_breakdown: breakdown, rejected_list: rejected } },
];

// Split normalizer output into 2 streams for the 2 downstream Supabase nodes.
const all = $input.all();
const cleanItem = all.find((i) => i.json.type === 'clean_posts');
const temporalItem = all.find((i) => i.json.type === 'temporal_rows');
const statsItem = all.find((i) => i.json.type === 'stats');
const cleanRows = (cleanItem?.json.items || []).map((r) => ({ json: r }));
const temporalRows = (temporalItem?.json.items || []).map((r) => ({ json: { ...r, format_distribution: JSON.stringify(r.format_distribution) } }));
return [cleanRows, temporalRows, [{ json: statsItem?.json || {} }]];

